// @generated end

function shapesOf(art: readonly Art[]): BodyShape[] {
  return art.map(([regions, d]) => {
    const shape: BodyShape = { d, region: regions[0] ?? null };
    // only spell out the list when it says more than `region` does
    if (regions.length > 1) shape.regions = [...regions];
    return shape;
  });
}

export const BODY_FIGURES: Record<BodyView, BodyFigure> = {
  front: { view: "front", viewBox: VIEW_BOX, outline: FRONT_OUTLINE, shapes: shapesOf(FRONT_ART) },
  back: { view: "back", viewBox: VIEW_BOX, outline: BACK_OUTLINE, shapes: shapesOf(BACK_ART) },
};

/** every region a shape lights up (empty for head, hands, joints) */
export function shapeRegions(shape: BodyShape): MuscleRegion[] {
  if (shape.regions && shape.regions.length > 0) return shape.regions;
  return shape.region ? [shape.region] : [];
}

/** the load a shape shows: the heaviest of its regions, undefined when none is loaded */
export function shapeLoad(shape: BodyShape, load: Partial<Record<MuscleRegion, number>>): number | undefined {
  let best: number | undefined;
  for (const r of shapeRegions(shape)) {
    const v = load[r];
    if (typeof v === "number" && Number.isFinite(v) && (best === undefined || v > best)) best = v;
  }
  return best;
}

const VIEWS: readonly BodyView[] = ["front", "back"];

/** which views show a region (e.g. lats: back; chest: front; side delts: both) */
export function viewsForRegion(region: MuscleRegion): BodyView[] {
  return VIEWS.filter((v) => BODY_FIGURES[v].shapes.some((s) => shapeRegions(s).includes(region)));
}

/**
 * map a normalized load (0..1) to a discrete intensity step 0..steps, so the
 * site and the phone shade the same way. 0 only for no load at all.
 */
export function loadIntensity(load: number | undefined, steps = 4): number {
  const n = Number.isFinite(steps) ? Math.max(1, Math.floor(steps)) : 4;
  if (load === undefined || !(load > 0)) return 0;
  // any load at all shows at least the faintest step
  return Math.min(n, Math.max(1, Math.ceil(load * n)));
}
